{
  "ok": true,
  "summary": "Surface reconnaissance complete. Discovered live OWASP Juice Shop at http://127.0.0.1:3010 with Express ^4.22.1 backend, Angular SPA frontend, SQLite database, and JWT-based auth. Major findings include exposed REST API endpoints (products, users, feedbacks, challenges, quantities, memories), directory listing on /ftp with null-byte path traversal bypass for sensitive file access, full application configuration exposed without auth, mass assignment vulnerability to escalate to admin role, SQL injection in product search, password hashes leaked via /rest/memories endpoint, and administrative API endpoints accessible with weak credentials (admin:admin123). Stage criteria met: multiple live surfaces recorded.",
  "surfaces": [
    {
      "type": "url",
      "value": "http://127.0.0.1:3010",
      "label": "Main web application - OWASP Juice Shop SPA",
      "proof": "HTTP 200 - Angular/Express application serving HTML with title 'OWASP Juice Shop'. Response includes 'x-recruiting' header pointing to /#/jobs."
    },
    {
      "type": "api",
      "value": "http://127.0.0.1:3010/api/products",
      "label": "Product catalog API (no auth required)",
      "proof": "GET /api/products returns 200 with JSON containing all products including id, name, price, deluxePrice, image, description."
    },
    {
      "type": "api",
      "value": "http://127.0.0.1:3010/api/Users",
      "label": "User management API (POST registration no auth, GET requires auth)",
      "proof": "POST /api/Users with role=admin registers admin user successfully (201). GET /api/Users with Bearer token returns all users with roles and emails."
    },
    {
      "type": "api",
      "value": "http://127.0.0.1:3010/api/Challenges",
      "label": "Challenge definitions API (no auth required)",
      "proof": "GET /api/Challenges returns 200 with full challenge definitions including names, categories, difficulty levels, descriptions."
    },
    {
      "type": "api",
      "value": "http://127.0.0.1:3010/api/Feedbacks",
      "label": "User feedback API (no auth required)",
      "proof": "GET /api/Feedbacks returns 200 with feedback comments including partially masked email addresses and user IDs."
    },
    {
      "type": "api",
      "value": "http://127.0.0.1:3010/api/Quantitys",
      "label": "Product inventory API (no auth required)",
      "proof": "GET /api/Quantitys returns 200 with all product quantities and per-user limits."
    },
    {
      "type": "api",
      "value": "http://127.0.0.1:3010/rest/products/search",
      "label": "Product search API with SQL injection (no auth required)",
      "proof": "GET /rest/products/search?q=' OR 1=1-- returns SQLITE_ERROR confirming SQL injection. Normal query returns product list."
    },
    {
      "type": "api",
      "value": "http://127.0.0.1:3010/rest/user/login",
      "label": "Authentication API (POST, JWT-based)",
      "proof": "POST /rest/user/login with JSON body returns JWT token. Login with admin@juice-sh.op / admin123 successfully returns admin token."
    },
    {
      "type": "api",
      "value": "http://127.0.0.1:3010/rest/admin/application-configuration",
      "label": "Application configuration API (no auth required - sensitive data exposure)",
      "proof": "GET /rest/admin/application-configuration returns full config including server details, OAuth client ID, challenge settings, product data, chatbot config, and social media URLs."
    },
    {
      "type": "api",
      "value": "http://127.0.0.1:3010/rest/memories",
      "label": "User memories API (no auth - password hash leak)",
      "proof": "GET /rest/memories returns user memories with embedded user objects containing email, password hash, role, and deluxeToken for multiple users including admins."
    },
    {
      "type": "file",
      "value": "http://127.0.0.1:3010/ftp/",
      "label": "Exposed FTP directory listing",
      "proof": "GET /ftp/ returns directory listing with 11 files: acquisitions.md, announcement_encrypted.md, coupons_2013.md.bak, eastere.gg, encrypt.pyc, incident-support.kdbx, legal.md, package-lock.json.bak, package.json.bak, suspicious_errors.yml, and quarantine/ subdirectory."
    },
    {
      "type": "file",
      "value": "http://127.0.0.1:3010/robots.txt",
      "label": "Robots.txt exposing /ftp directory",
      "proof": "GET /robots.txt returns 'User-agent: *\nDisallow: /ftp'"
    },
    {
      "type": "client",
      "value": "http://127.0.0.1:3010/#/",
      "label": "Angular SPA client-side routes",
      "proof": "HTML source contains Angular template routes including /#/jobs, /#/recycle, /#/score-board, /#/forgot-password, /#/bee-haven"
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:3010/the/devs/are/so/funny/they/hid/an/easter/egg/within/the/easter/egg",
      "label": "Hidden easter egg page (3D planet visualization)",
      "proof": "ROT13-decoded path from eastere.gg leads to a Three.js-powered 3D planet visualization using private assets."
    }
  ],
  "candidates": [
    {
      "title": "Mass Assignment - Admin Privilege Escalation",
      "location": "POST /api/Users",
      "proof_excerpt": "POST /api/Users with {\"email\":\"admin2@test.com\",\"password\":\"admin123\",\"username\":\"admin2\",\"role\":\"admin\"} returns 201 with role:admin confirmed in response. Challenge 'Admin Registration' marked as solved.",
      "poc_hint": "Register new user with role:admin field to escalate privileges"
    },
